#include <iostream>
#include <vector>

int main() {
    std::vector<int> numbers = {10, 20, 30};  // A simple vector of integers
    for (auto elem : numbers) {  // auto deduces elem as int
        std::cout << "Element: " << elem << std::endl;  // Processes each element
    }
    auto sum = 0;  // auto deduces sum as int from the initializer 0
    for (auto num : numbers) {
        sum += num;  // Accumulates the sum
    }
    std::cout << "Total sum: " << sum << std::endl;  // Outputs the result
    return 0;
}
